package com.chiarasystems.chiara.designsystem

import androidx.compose.runtime.Composable
import androidx.compose.runtime.staticCompositionLocalOf
import java.util.Locale

/**
 * Port of iOS `tr(_:)`: the key is the Spanish source text; [table] is the catalog of the language in use
 * (generated by `scripts/xcstrings-to-json.mjs`). A missing key falls back to the key itself.
 */
class Translator(val code: String, private val table: Map<String, String> = emptyMap()) {
    fun tr(key: String): String = table[key] ?: key
    fun tr(key: String, vararg args: Any?): String =
        String.format(Locale.forLanguageTag(code), tr(key), *args)
}

val LocalTranslator = staticCompositionLocalOf { Translator("es") }

@Composable
fun tr(key: String): String = LocalTranslator.current.tr(key)

@Composable
fun tr(key: String, vararg args: Any?): String = LocalTranslator.current.tr(key, *args)
